float s314_opt(int iterations, int LEN_1D, float* a) {
    float x;
    for (int nl = 0; nl < iterations*5; nl++) {
        x = a[0];
        for (int i = 0; i < LEN_1D; i++) {
            float current = a[i];
            if (current > x) {
                x = current;
            }
        }
    }
    return x;
}

float vectorized_s314(int iterations, int LEN_1D, float* a) {
    float x;
    int outer_iterations = iterations * 5;

    for (int nl = 0; nl < outer_iterations; nl++) {
        x = a[0];

        // Vectorized reduction for max operation
        typedef float v4f __attribute__((vector_size(16)));
        const int VEC_SIZE = 4;

        // Process vectorizable portion
        int i = 0;
        v4f vmax = {x, x, x, x};

        for (; i + VEC_SIZE <= LEN_1D; i += VEC_SIZE) {
            v4f vcurrent = *(v4f*)&a[i];
            // Use builtin elementwise max for portable vector maximum
            vmax = __builtin_elementwise_max(vcurrent, vmax);
        }

        // Extract horizontal maximum from vector
        float max_arr[4];
        *(v4f*)max_arr = vmax;
        float vec_max = max_arr[0];
        for (int j = 1; j < 4; j++) {
            if (max_arr[j] > vec_max) {
                vec_max = max_arr[j];
            }
        }

        // Combine vector result with scalar initialization
        if (vec_max > x) {
            x = vec_max;
        }

        // Process remaining elements
        for (; i < LEN_1D; i++) {
            float current = a[i];
            if (current > x) {
                x = current;
            }
        }
    }

    return x;
}
